/**
 * Avenues: each institution's escalation roadmap, and every case email placed on it.
 *
 * Generated 19 October 2026 from Sion Buckler's Gmail (read-only, sent mail and inbox,
 * through 18 October 2026) by the same pass that built foi-tracker.ts. Privacy: no email
 * addresses, phone numbers or contact details; subjects are scrubbed and officials appear by
 * role only. Outcomes ("o") are read mechanically from each reply and can be wrong; the
 * hand-checked levels carry a "hand" note. Contested history is attributed to the named person who gave it, or marked SOURCE PENDING.
 * Nothing here is a finding of fact or of wrongdoing.
 *
 * Sources for the roadmaps (checked 19 Oct 2026):
 *  - FOIA 2000 s.1, s.10 (20 working days), s.3(2)(b) (information held on an authority's
 *    behalf), s.32 (court records), s.45 Code of Practice §5 (internal review: 20, max 40
 *    working days), s.50 (ICO), s.57 (First-tier Tribunal), s.59 + TCEA 2007 s.11 (Upper Tribunal).
 *    GRC Rules 2009 r.22 (28 days to appeal a decision notice).
 *  - EIR 2004 reg. 2(2) (public authority), reg. 5, reg. 11 (reconsideration, 40 working days),
 *    reg. 18 (FOIA enforcement applies). Water companies are EIR public authorities:
 *    Fish Legal v Information Commissioner [2015] UKUT 52 (AAC), after CJEU C-279/12.
 *  - UK GDPR Art. 12(3), 15 (subject access, one month, +2 months); DPA 2018 s.45 (law
 *    enforcement processing), s.165 (complaint to the ICO). Deceased people are outside UK GDPR;
 *    Access to Health Records Act 1990 covers deceased patients' records.
 *  - Public Services Ombudsman (Wales) Act 2019 Sch. 3 (includes county and community councils,
 *    Welsh Government, NHS Wales bodies). legislation.gov.uk/anaw/2019/3/schedule/3
 *  - Parliamentary Commissioner Act 1967 s.5(1) (PHSO complaints referred by an MP).
 *  - Police Reform Act 2002 Sch. 3 (police complaints, reviews by IOPC or local policing body).
 *  - CPS Feedback and Complaints Policy (stage 1, stage 2, Independent Assessor of Complaints).
 *  - HM Land Registry complaints procedure, then the Independent Complaints Reviewer.
 *    Land Registration Act 2002 s.65 + Sch. 4 (alteration / rectification), s.73 (objections to
 *    the First-tier Tribunal, Property Chamber), Sch. 8 (indemnity).
 *  - CPR 5.4C (non-party access to court records); Coroners (Inquests) Rules 2013 r.27.
 *  - Practice Direction – Pre-Action Conduct and Protocols (letter before claim).
 *  - CPR 31.16 (pre-action disclosure), CPR 31.17 (non-party disclosure),
 *    Norwich Pharmacal Co v Customs and Excise Commissioners [1974] AC 133.
 *  - Heneb: formed 1 Apr 2024 from the four Welsh Archaeological Trusts (incl. GGAT); a charity,
 *    not in FOIA Sch. 1. Cadw: "Heneb … maintains the historic environment records on behalf of
 *    the Welsh Ministers" (cadw.gov.wales/advice-support/placemaking/historic-environment-records);
 *    Historic Environment (Wales) Act 2023 ss.194–195. Its EIR status is arguable, unverified.
 *  - Charities Act 2011 (Charity Commission); CIfA register of Registered Organisations.
 */

import rampsJson from "./ramps.json";
import corrJson from "./correspondence.json";

/**
 * Per-institution ramps (20 Oct 2026): each institution's own disclosure ladder, built from UK law
 * (legislation.gov.uk), ICO guidance and the body's own published policies. Stored as data in
 * ramps.json; applyRamps() turns each rung into a girder of the climb and carries the emails of the
 * matching avenue onto it (field "em"). Rung states: done / pending / overdue / open / na.
 */
export type RampState = "done" | "pending" | "queued" | "overdue" | "open" | "na";
export type Rung = {
  k: string;
  ph: PhaseKey;
  t: string;
  s: string;
  w: string;
  law: string;
  url: string;
  time: string;
  cost: string;
  st: RampState;
  did?: string;
  next?: string;
  pol?: string;
  polurl?: string;
  em?: PhaseKey[];
  /** Legal Wiki evidence pages behind this rung. */
  ev?: { id: string; url: string }[];
};
export type RampInstitution = { id: string; name: string; short: string; kind: string; regimes: string[]; note: string; rungs: Rung[]; new: boolean };
export type RampData = { asOf: string; note: string; states: Record<RampState, string>; institutions: RampInstitution[] };
export const ramps = rampsJson as unknown as RampData;
export const rampStateInfo: Record<RampState, { label: string; status: AvStatus }> = {
  done: { label: "Done", status: "done" },
  pending: { label: "Pending: waiting on them", status: "progress" },
  queued: { label: "Queued: drafted, not sent", status: "available" },
  overdue: { label: "Overdue", status: "overdue" },
  open: { label: "Open: not used yet", status: "available" },
  na: { label: "Not available / not used", status: "na" },
};
/** A rung that itself costs money (its cost starts with PAID). "Free (copies PAID)" is a free rung. */
export const isPaid = (r: Rung) => /^PAID/.test(r.cost);

export type PhaseKey = "enquiry" | "foi" | "eir" | "sar" | "review" | "complaint" | "ico" | "icr" | "psow" | "phso" | "iopc" | "iac" | "ccw" | "charity" | "regulator" | "democratic" | "petition" | "register" | "courtrec" | "tribunal" | "preaction" | "disclosure";
export type AvStatus = "done" | "progress" | "overdue" | "available" | "na";
export type Outcome = "sent" | "auto" | "ack" | "reply" | "answered" | "notheld" | "refused";
export type Phase = { name: string; short: string; what: string; law: string };
/** One email. d = date, o = outcome (mechanical), s = subject (scrubbed), r = official refs, t = thread, i = institutions it counts for. */
export type AvDoc = { label: string; url: string; wayback?: string };
/**
 * Optional extras, filled by hand for replies whose substance sits in an attached letter:
 * from = sender by role; sum = one-line summary; q = verbatim key quotes from the letter; pdf = the letter itself
 * (public copy, personal contact details redacted) on this site and in the Wayback archive.
 */
export type AvEmail = { d: string; out: boolean; o: Outcome; s: string; r: string[]; t: string; i: string[]; from?: string; sum?: string; q?: string[]; pdf?: AvDoc[] };
export type AvLevel = {
  phase: PhaseKey;
  applicable: boolean;
  /** Why this avenue does or does not apply to this institution. */
  note: string;
  status: AvStatus;
  /** Earliest open statutory deadline (computed, about). */
  deadline: string;
  /** Indexes into avenueEmails, oldest first. */
  items: number[];
  /** Threads still waiting on an answer. */
  open: string[];
  /** Threads hand-checked as overdue. */
  late: string[];
  /** Hand-checked note, when there is one. */
  hand: string;
  /** This institution's own rung (from ramps.json), when the ramp is tailored. */
  rung?: Rung;
};
export type AvInstitution = { id: string; name: string; short: string; kind: string; wheel: string[]; levels: AvLevel[]; ramp?: RampInstitution };

