export function emailUrl(index: number): { url: string; exact: boolean } {
  const direct = emailLinks[index];
  if (direct) return { url: direct, exact: true };
  const e = avenueEmails[index];
  const p = new URLSearchParams();
  p.set("title", e.s);
  p.set("date", e.d);
  if (e.r.length) p.set("caseRef", e.r.join(", "));
  return { url: `https://email.bucklerfamily.estate/reference/${e.t}?${p.toString()}`, exact: false };
}

/** One number per institution, shared by its dropdown entry and its outer wheel slice. */
export const instNumber = (id: string) => institutions.findIndex((i) => i.id === id) + 1;
